def step(n,title,desc,settings=None,banners=(),machine=None,fig=None):
    return {"stepNumber":n,"title":title,"description":desc,"settings":settings or {},"safetyBanners":[B[b] for b in banners],"machineSetup":machine,"figureType":fig}
