def renum(steps):
    seen={}
    for i,s in enumerate(steps,1):
        s["stepNumber"]=i
        base=re.sub(r"[^a-z0-9]+","-",s["title"].lower()).strip("-")
        seen[base]=seen.get(base,0)+1
        s["stepId"]=base if seen[base]==1 else f"{base}-{seen[base]}"
    return steps
